static readonly ConditionalWeakTable<Document, SpellState> State =
    new ConditionalWeakTable<Document, SpellState>();
static SpellState Spell(this Document d) =>
    State.TryGetValue(d, out var s) ? s : null;   // null == capability absent

State.GetOrAdd(doc, _ => new SpellState(dictionary)).Enabled = true;
var state = doc.Spell();
if (state != null && state.Enabled) SpellCheck(doc);

